public class GcdCalculatorCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(GcdCalculator impl) {
        try {
            return GcdCalculatorChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectGcd()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectGcd()));
        check("rejects the negative answer", false, verdict(new SignBlindGcd()));
        check("rejects the crash when one argument is zero", false, verdict(new ZeroCrashGcd()));
        check("rejects the search that starts one divisor too low", false, verdict(new OffByOneGcd()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectGcd implements GcdCalculator {
    public int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}

class AlsoCorrectGcd implements GcdCalculator {
    public int gcd(int a, int b) {
        return b == 0 ? Math.abs(a) : gcd(b, a % b);
    }
}

class SignBlindGcd implements GcdCalculator {
    public int gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}

class ZeroCrashGcd implements GcdCalculator {
    public int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        int remainder = a % b;
        while (remainder != 0) {
            a = b;
            b = remainder;
            remainder = a % b;
        }
        return b;
    }
}

class OffByOneGcd implements GcdCalculator {
    public int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        if (a == 0) return b;
        if (b == 0) return a;
        for (int d = Math.min(a, b) - 1; d >= 1; d--) {
            if (a % d == 0 && b % d == 0) return d;
        }
        return 1;
    }
}

