/**
 * TASK: Write the checks that decide whether a GcdCalculator is correct.
 *
 *   gcd(a, b) returns the greatest common divisor of a and b.
 *   The answer is never negative: gcd(-12, 18) is 6, not -6.
 *   gcd(0, n) and gcd(n, 0) are both |n|, and gcd(0, 0) is 0.
 *   Examples: gcd(12, 18) -> 6,  gcd(6, 3) -> 3,  gcd(7, 13) -> 1
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
interface GcdCalculator {
    /* Provided -- do not edit. */
    int gcd(int a, int b);
}

public class GcdCalculatorChecker {

    public static boolean isCorrect(GcdCalculator impl) {
        try {
            if (impl.gcd(12, 18) != 6) return false;
            if (impl.gcd(6, 3) != 3) return false;
            if (impl.gcd(7, 13) != 1) return false;
            if (impl.gcd(0, 5) != 5) return false;
            if (impl.gcd(5, 0) != 5) return false;
            if (impl.gcd(0, 0) != 0) return false;
            if (impl.gcd(-12, 18) != 6) return false;
            if (impl.gcd(12, -18) != 6) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
